changeSet.sql:
        	 update kb_email_template set xkey='user-defined-alert' where xkey='work-note';
        	 update kb_email_template set subject = replace(subject, 'work-note', 'alert');
			 update kb_email_template set strtext = replace(strtext, 'work-note', 'alert');		
			 update kb_email_template set available_macros  = replace(available_macros, 'Work Note', 'Alert');

update rs_windsor_activity_pivot pvtUp
set reason = (select pvt2.reason from  rs_windsor_activity_pivot pvt2 where pvt2.id = (select min(id) from rs_windsor_activity_pivot pvt3 where pvtUp.process=pvt3.process and pvtUp.id<pvt3.id) )
where event = 'collaboration_request' and reason is null;

update dataset set alias =  replace(initcap(name), ' ', '');
update kb_classifier set alias =  replace(initcap(name), ' ', '');
update kb_classifier set predicate  = replace(initcap(name), ' ', '');

alter table kb_contenttemplate add column if not exists alias character varying(64);
update kb_contenttemplate set alias = replace(initcap(name), ' ', '');

alter table logevent add column if not exists event_content_xid bigint;
update logevent set event_content_xid = cast( split_part( event_object_id, '#', 2) as integer ) where 
event_content_xid is null and 
event_content_id is not null and 
event_object_id is not null and 
split_part( event_object_id, '#', 2) is not null;

alter table logevent add column if not exists event_type_int integer;

