CREATE TABLE if not exists kb_enotirule_role (
	rule_id bigint NOT NULL,
	role_id bigint NOT NULL
)
wITH (
	OIDS = FALSE
);

ALTER TABLE ONLY kb_enotirule_role	DROP CONSTRAINT IF EXISTS enotirule_role_pkey;
ALTER TABLE ONLY kb_enotirule_role	ADD CONSTRAINT            enotirule_role_pkey PRIMARY KEY (rule_id, role_id);

ALTER TABLE ONLY kb_enotirule_role	DROP CONSTRAINT IF EXISTS role_fk;
ALTER TABLE ONLY kb_enotirule_role	ADD CONSTRAINT 			  role_fk FOREIGN KEY (role_id) REFERENCES kb_role(id) ON DELETE CASCADE;


alter table resourcegroup add column if not exists creationdate    timestamp with time zone default now();
alter table resourcegroup add column if not exists lastmodifieddate timestamp with time zone default now();
alter table resourcegroup add column if not exists  lastmodifieduser bigint references users(id) on delete restrict;
alter table resourcegroup add column if not exists  domain_id bigint references domain(id) on delete cascade;
alter table resourcegroup add column if not exists  alias            character varying(256);
alter table resourcegroup add column if not exists  state            integer default 1;
alter table resourcegroup add column if not exists  createuser       bigint references users(id) on delete restrict;


